"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[51157],{3331:(e,n,i)=>{i.d(n,{R:()=>a,x:()=>l});var r=i(36672);const t={},s=r.createContext(t);function a(e){const n=r.useContext(s);return r.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function l(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),r.createElement(s.Provider,{value:n},e.children)}},88091:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>d,contentTitle:()=>l,default:()=>o,frontMatter:()=>a,metadata:()=>r,toc:()=>h});const r=JSON.parse('{"id":"2023/04/02","title":"02","description":"Amazon Echo-Ger\xe4te speichern WiFi-Passw\xf6rter im Klartext, was sie anf\xe4llig f\xfcr physische Angriffe macht","source":"@site/i18n/de/docusaurus-plugin-content-docs/current/2023/04/02.md","sourceDirName":"2023/04","slug":"/2023/04/02","permalink":"/de/2023/04/02","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/de/docusaurus-plugin-content-docs//current/2023/04/02.md","tags":[],"version":"current","frontMatter":{"localized_date":"2. April 2023","top_news":"Amazon Echo-Ger\xe4te speichern WiFi-Passw\xf6rter im Klartext, was sie anf\xe4llig f\xfcr physische Angriffe macht"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-03","permalink":"/de/2023/04/03"},"next":{"title":"01","permalink":"/de/2023/04/01"}}');var t=i(23420),s=i(3331);const a={localized_date:"2. April 2023",top_news:"Amazon Echo-Ger\xe4te speichern WiFi-Passw\xf6rter im Klartext, was sie anf\xe4llig f\xfcr physische Angriffe macht"},l=void 0,d={},h=[{value:"Amazon Echo-Ger\xe4te speichern WiFi-Passw\xf6rter im Klartext, was sie anf\xe4llig f\xfcr physische Angriffe macht",id:"amazon-echo-ger\xe4te-speichern-wifi-passw\xf6rter-im-klartext-was-sie-anf\xe4llig-f\xfcr-physische-angriffe-macht",level:2},{value:"Google Drive f\xfchrt Dateibeschr\xe4nkungen ein und sperrt m\xf6glicherweise zahlende Kunden aus",id:"google-drive-f\xfchrt-dateibeschr\xe4nkungen-ein-und-sperrt-m\xf6glicherweise-zahlende-kunden-aus",level:2},{value:"Guide to Logical Clock Designs for Reliable Event Ordering in Distributed Systems",id:"guide-to-logical-clock-designs-for-reliable-event-ordering-in-distributed-systems",level:2},{value:"Frankreichs 3034 km langer HexaTrek-Weg f\xfcr Wanderungen ge\xf6ffnet",id:"frankreichs-3034-km-langer-hexatrek-weg-f\xfcr-wanderungen-ge\xf6ffnet",level:2},{value:"Entwickler Raph Levien wechselt von Rust zu C++",id:"entwickler-raph-levien-wechselt-von-rust-zu-c",level:2},{value:"Coursemate: Weltweite Vernetzung von SelbstlernerInnen f\xfcr kollaboratives Online-Lernen",id:"coursemate-weltweite-vernetzung-von-selbstlernerinnen-f\xfcr-kollaboratives-online-lernen",level:2},{value:"Pflanzen geben bei Stress Ger\xe4usche von sich, was neue M\xf6glichkeiten des Verst\xe4ndnisses er\xf6ffnet",id:"pflanzen-geben-bei-stress-ger\xe4usche-von-sich-was-neue-m\xf6glichkeiten-des-verst\xe4ndnisses-er\xf6ffnet",level:2},{value:"Simulation eines unterirdischen BBS-Systems von 1987: Chat, Spiele und E-Mail",id:"simulation-eines-unterirdischen-bbs-systems-von-1987-chat-spiele-und-e-mail",level:2},{value:"Google verz\xf6gert die Abschaltung von Manifest V2 f\xfcr Chrome-Erweiterungen",id:"google-verz\xf6gert-die-abschaltung-von-manifest-v2-f\xfcr-chrome-erweiterungen",level:2},{value:"Wine 8.5: Verbessertes vkd3d, WinRT Theme und Fehlerbehebungen",id:"wine-85-verbessertes-vkd3d-winrt-theme-und-fehlerbehebungen",level:2},{value:"Resume-First Hiring Process: Ausbeuterisch &amp; ineffektiv",id:"resume-first-hiring-process-ausbeuterisch--ineffektiv",level:2},{value:"Ex-SpaceX-Mitarbeiter gr\xfcnden Dutzende von Weltraum-Startups und sammeln 3,6 Milliarden Dollar ein",id:"ex-spacex-mitarbeiter-gr\xfcnden-dutzende-von-weltraum-startups-und-sammeln-36-milliarden-dollar-ein",level:2},{value:"SpaceX&#39;s Starship bewegt sich zum Startplatz, Start m\xf6glicherweise am 10. April",id:"spacexs-starship-bewegt-sich-zum-startplatz-start-m\xf6glicherweise-am-10-april",level:2},{value:"ccurl.sh&#39; erm\xf6glicht es cURL, Chrome-Cookies auf eine \xfcbersichtliche Weise zu nutzen.",id:"ccurlsh-erm\xf6glicht-es-curl-chrome-cookies-auf-eine-\xfcbersichtliche-weise-zu-nutzen",level:2},{value:"MIT&#39;s Course on RNNs &amp; Transformers for Deep Learning",id:"mits-course-on-rnns--transformers-for-deep-learning",level:2}];function u(e){const n={a:"a",h2:"h2",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.h2,{id:"amazon-echo-ger\xe4te-speichern-wifi-passw\xf6rter-im-klartext-was-sie-anf\xe4llig-f\xfcr-physische-angriffe-macht",children:"Amazon Echo-Ger\xe4te speichern WiFi-Passw\xf6rter im Klartext, was sie anf\xe4llig f\xfcr physische Angriffe macht"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Alexa, wie lautet mein WiFi-Passwort?"}),"\nAmazon Echo-Ger\xe4te speichern WiFi-Passw\xf6rter im Klartext, was es Angreifern mit physischem Zugang erm\xf6glicht, Netzwerkpassw\xf6rter relativ einfach zu extrahieren. Dies stellt ein gro\xdfes Sicherheitsrisiko f\xfcr Hotels oder Unternehmen dar, die die Ger\xe4te in ihren internen oder privaten drahtlosen Netzwerken verwenden, da Angreifer Zugang zu allen anderen Ger\xe4ten im Netzwerk erhalten und m\xf6glicherweise gegen das Datenschutzgesetz versto\xdfen. Das Hashing von Passw\xf6rtern ist ein Industriestandard, und f\xfcr ein Unternehmen, das seine Hardware millionenfach verkauft hat, ist es v\xf6llig inakzeptabel, diese Daten nicht zu verschl\xfcsseln. Das Ger\xe4t verschl\xfcsselt die API-Schl\xfcssel f\xfcr Spotify zeroconf und eSDK APIs nicht. Physikalische Sicherheit ist bei der Entwicklung eingebetteter Hardware unerl\xe4sslich, und Amazon muss dieses Problem angehen, um k\xfcnftige Sicherheitsl\xfccken zu verhindern.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35399590",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://dragon863.github.io/blog/alexa.html",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"google-drive-f\xfchrt-dateibeschr\xe4nkungen-ein-und-sperrt-m\xf6glicherweise-zahlende-kunden-aus",children:"Google Drive f\xfchrt Dateibeschr\xe4nkungen ein und sperrt m\xf6glicherweise zahlende Kunden aus"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Google Drive f\xfchrt \xfcberraschend ein Dateilimit ein und sperrt einige Nutzer aus"}),".\nGoogle Drive hat ohne Vorwarnung ein Dateilimit eingef\xfchrt, das m\xf6glicherweise zahlende Kunden von neuen Datei-Uploads ausschlie\xdft; Reddit-Nutzer haben sich bereits in den letzten zwei Monaten \xfcber dieses Problem beschwert. Die pl\xf6tzliche Einf\xfchrung eines Dateilimits wird weder auf den Seiten der Google One- oder Google Workspace-Tarife aufgef\xfchrt noch in Support-Dokumenten erw\xe4hnt. Es hat die Nutzer auch daran gehindert, den von ihnen erworbenen Speicherplatz zu nutzen, da das Limit sie daran hindert, den Speicherplatz zu verwenden. Die Begrenzung von Google Drive auf 5 Millionen Dateien wird von vielen Nutzern weder als akzeptabel noch als vern\xfcnftig angesehen, da sie nirgends dokumentiert ist, und die Kosten f\xfcr die Nutzung des Speicherplans von Google Workspace werden als exorbitant hoch angesehen. Google argumentiert, dass die Begrenzung eine Schutzma\xdfnahme ist, um Systemmissbrauch zu verhindern, der die Stabilit\xe4t und Sicherheit des Systems beeintr\xe4chtigen k\xf6nnte, doch eine solche Kundenkommunikation wird als schlecht angesehen.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35397071",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://arstechnica.com/gadgets/2023/03/google-drive-does-a-surprise-rollout-of-file-limits-locking-out-some-users/",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"guide-to-logical-clock-designs-for-reliable-event-ordering-in-distributed-systems",children:"Guide to Logical Clock Designs for Reliable Event Ordering in Distributed Systems"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Clocks and Causality - Ordering Events in Distributed Systems (2022)."}),"\nLogische Uhren sind f\xfcr die Ordnung von Ereignissen in verteilten Systemen unerl\xe4sslich, wobei Lamport- und Vektoruhren beliebte Designs sind. Lamport-Uhren liefern aufsteigende Nummern innerhalb eines Knotens, w\xe4hrend Vektor-Uhren Knoten-IDs und entsprechende Ereignis-IDs f\xfcr gleichzeitige Ereignisvergleiche verfolgen. Gepunktete Vektor-Uhren und Vektor-Zeitstempel optimieren die Zeitstempelpr\xfcfung und erm\xf6glichen eine knoten\xfcbergreifende Ereignisordnung. Versionsvektoren verfolgen Datenversionen in mehrstufigen Speicherknoten. Lamport Causal Clock erfasst die Kausalit\xe4t, ben\xf6tigt aber mehr Platz und Zeitkomplexit\xe4t. Total Order erfordert eine sequentielle Anordnung auf der Grundlage zeitlicher und kausaler Beziehungen. Logische Uhren sind in Anwendungen f\xfcr die gemeinsame Bearbeitung von Inhalten von entscheidender Bedeutung. Azure Time Sync verwendet PTP, w\xe4hrend AWS und Google Cloud NTP verwenden. Der Artikel weist auf die Einschr\xe4nkungen hin, die sich aus dem Versuch ergeben, Zeit als absolut zu betrachten, und betont die Bedeutung der Ereignisreihenfolge bei Banktransaktionen.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35399603",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://www.exhypothesi.com/clocks-and-causality/",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"frankreichs-3034-km-langer-hexatrek-weg-f\xfcr-wanderungen-ge\xf6ffnet",children:"Frankreichs 3034 km langer HexaTrek-Weg f\xfcr Wanderungen ge\xf6ffnet"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Hexatrek: Die Langstreckenwanderung in Frankreich."}),"\nFrankreichs 3034 km langer HexaTrek-Wanderweg ist jetzt zum Durchwandern freigegeben. Er verbindet 14 Nationalparks und kreuzt die rum\xe4nische Via Transilvanica.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35397051",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://en.hexatrek.com",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"entwickler-raph-levien-wechselt-von-rust-zu-c",children:"Entwickler Raph Levien wechselt von Rust zu C++"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Umzug von Rust zu C++."}),"\nDer Entwickler Raph Levien gibt die Entscheidung bekannt, von Rust zu C++ zu wechseln, da Rust trotz seiner Sicherheitsgarantien zu wenig Auswahlm\xf6glichkeiten f\xfcr das Build-System bietet und nur langsam Innovationen hervorbringt. Levien ist der Meinung, dass er Sicherheitsprobleme vermeiden kann und dass Speicher-Sicherheitsfehler nicht wesentlich sch\xe4dlicher sind als andere Fehler, und dass C++ sich schnell weiterentwickelt, um sicherer zu werden. Levien unterstreicht die Bedeutung der Gemeinschaft und \xe4u\xdfert Bedenken \xfcber diskriminierende Ma\xdfnahmen und scheinbar \xfcberhebliche Rust-Bef\xfcrworter. Der Artikel ist jedoch satirisch, und einige Leser bekunden ihr Interesse an C++ gegen\xfcber Rust.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35400047",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://raphlinus.github.io/rust/2023/04/01/rust-to-cpp.html",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"coursemate-weltweite-vernetzung-von-selbstlernerinnen-f\xfcr-kollaboratives-online-lernen",children:"Coursemate: Weltweite Vernetzung von SelbstlernerInnen f\xfcr kollaboratives Online-Lernen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Discussion Service anzeigen: Coursemate - mit anderen Selbstlernern in Verbindung treten"}),".\nCoursemate ist eine Plattform f\xfcr Selbstlerner, die sich mit Gleichgesinnten in ihrem Land oder auf der ganzen Welt verbinden und gemeinsam an Online-Kursen arbeiten m\xf6chten. Die Plattform kann in die bevorzugten Online-Kurse der Nutzer integriert werden und ist in weniger als einer Minute eingerichtet. Einige Nutzer schlagen vor, dass Coursemate von spezifischeren Lernzielen profitieren k\xf6nnte, die \xfcber den derzeitigen Fokus auf Frontend- und Backend-Themen hinausgehen. Au\xdferdem w\xfcnschen sich die Nutzer mehr Beispiele aus der Community und M\xf6glichkeiten f\xfcr Mentoren. Einige Nutzer schlagen auch vor, die Filterung nach Alter und Land zu erweitern, um eine Filterung nach Interessen zu erm\xf6glichen. Trotz einiger Kritikpunkte ist die Website gut aufgebaut und \xfcbersichtlich. Einige Nutzer w\xfcnschen sich eine Plattform, um mit Experten in Kontakt zu treten, die bei der Erkl\xe4rung bestimmter Kursinhalte helfen k\xf6nnen.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35398480",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://www.coursem8.com/",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"pflanzen-geben-bei-stress-ger\xe4usche-von-sich-was-neue-m\xf6glichkeiten-des-verst\xe4ndnisses-er\xf6ffnet",children:"Pflanzen geben bei Stress Ger\xe4usche von sich, was neue M\xf6glichkeiten des Verst\xe4ndnisses er\xf6ffnet"}),"\n",(0,t.jsxs)(n.p,{children:["**Ger\xe4usche, die Pflanzen unter Stress aussenden, sind \xfcber die Luft \xfcbertragen und informativ.\nPflanzen k\xf6nnen unter Stress informative Luftger\xe4usche aussenden, was neue M\xf6glichkeiten f\xfcr das Verst\xe4ndnis ihrer Interaktionen mit der Umwelt er\xf6ffnet. Dieser neue Bereich der Pflanzenbioakustik er\xf6ffnet das Potenzial f\xfcr die akustische Kommunikation von Pflanzen, die mit Hilfe von Modellen des maschinellen Lernens erkannt werden kann und die Landwirtschaft \xfcber die traditionellen Hinweise hinaus beeinflussen k\xf6nnte.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35396156",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://www.cell.com/cell/fulltext/S0092-8674(23)00262-3",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"simulation-eines-unterirdischen-bbs-systems-von-1987-chat-spiele-und-e-mail",children:"Simulation eines unterirdischen BBS-Systems von 1987: Chat, Spiele und E-Mail"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"ChatGPT simuliert das BBS-System von 1987"}),".\nDer Artikel beschreibt die Simulation eines BBS-Systems von 1987, einschlie\xdflich Chat, Spiele und E-Mail. BenutzerInnen k\xf6nnen ein Konto anlegen, Nachrichten und Dokumentation lesen, Textdateien ansehen und mit anderen BenutzerInnen kommunizieren. Castle Quest, ein textbasiertes Spiel, kann auf dem System gespielt werden. ShareGPT erm\xf6glicht den Austausch von Codeschnipseln in Unterhaltungen. Die historische Genauigkeit der ChatGPT-Ausgaben ist fragw\xfcrdig, aber interessant. Ein Benutzer schl\xe4gt vor, eine BBS von 1987 mit zus\xe4tzlichen Funktionen zu simulieren. Der Artikel bietet einen nostalgischen Blick auf die Technologie von damals.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35396165",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://sharegpt.com/c/ICZsSl7",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"google-verz\xf6gert-die-abschaltung-von-manifest-v2-f\xfcr-chrome-erweiterungen",children:"Google verz\xf6gert die Abschaltung von Manifest V2 f\xfcr Chrome-Erweiterungen"}),"\n",(0,t.jsxs)(n.p,{children:["**Verschiebung der Manifest V2-Abschaltung.\nGoogle hat die f\xfcr Januar geplanten Experimente zur Abschaltung von Manifest V2 in den Vorabversionen von Chrome und die \xc4nderungen am Featured Badge im Chrome Webstore verschoben und wird alle nachgelagerten Meilensteine pr\xfcfen. Entwicklern wird ausreichend Zeit gegeben, um ihre Erweiterungen nach der Einf\xfchrung dieser neuen Funktionen zu aktualisieren und zu testen, bevor Manifest V2 abgeschaltet wird. Es wird erwartet, dass Google mit der Einf\xfchrung von Manifest V3 die Sicherheit, den Datenschutz und die Leistung f\xfcr seine Nutzer verbessern wird. Es gab R\xfcckmeldungen aus der Entwickler-Community zu den Schwierigkeiten bei der Verwendung von Manifest V3, von denen einige bereits behoben wurden, aber es gibt immer noch Verbesserungen, und Google bleibt dem \xdcbergang verpflichtet.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35402698",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://groups.google.com/a/chromium.org/g/chromium-extensions/c/zQ77HkGmK9E/m/HjaaCIG-BQAJ",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"wine-85-verbessertes-vkd3d-winrt-theme-und-fehlerbehebungen",children:"Wine 8.5: Verbessertes vkd3d, WinRT Theme und Fehlerbehebungen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Wine 8.5."}),"\nWine Release 8.5 kommt mit verbessertem vkd3d, WinRT Theme und Fehlerkorrekturen, einschlie\xdflich besserer Fehlerberichterstattung im IDL-Compiler, Unterst\xfctzung f\xfcr UIA_IsOffscreenPropertyId f\xfcr MSAA-Provider und vollst\xe4ndige Initialisierung des i386 FPU-Kontextes auf ARM64. Bin\xe4rpakete sind f\xfcr verschiedene Distributionen verf\xfcgbar, und der Quellcode ist direkt im Git-Repository verf\xfcgbar. Fehlerkorrekturen umfassen mscoree, imm32 und LDAP bind.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35398643",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://www.winehq.org/announce/8.5",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"resume-first-hiring-process-ausbeuterisch--ineffektiv",children:"Resume-First Hiring Process: Ausbeuterisch & ineffektiv"}),"\n",(0,t.jsxs)(n.p,{children:["**Wer einen Lebenslauf einreicht, hat schon verloren.\nDas herk\xf6mmliche Einstellungsverfahren, bei dem der Lebenslauf an erster Stelle steht, ist ausbeuterisch und letztlich ineffektiv. Die Arbeitgeber nutzen es vor allem, um Zeit und Kosten auf Kosten der Bewerber zu sparen. Lebensl\xe4ufe k\xf6nnen vernachl\xe4ssigt werden, und pers\xf6nliche Empfehlungen und Netzwerke sind effektivere Methoden, um eine Stelle zu erhalten und das fehlerhafte und unfaire Verfahren zu umgehen. Die Einstellung von Akademikern ist unglaublich demoralisierend, und Vetternwirtschaft kann zu ethischen Problemen f\xfchren. Arbeitssuchende m\xfcssen tun, was sie k\xf6nnen, um das System zu umgehen, aber es ist dennoch notwendig, Lebensl\xe4ufe ernst zu nehmen. Der Beitrag bietet Tools, mit denen sich Arbeitssuchende von der Masse abheben k\xf6nnen, z. B. durch das Verfassen eines Anschreibens oder die Verwendung eines KI-Tools, das dieses in zwei Minuten verfasst.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35397271",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://www.residentcontrarian.com/p/he-who-submits-a-resume-has-already",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"ex-spacex-mitarbeiter-gr\xfcnden-dutzende-von-weltraum-startups-und-sammeln-36-milliarden-dollar-ein",children:"Ex-SpaceX-Mitarbeiter gr\xfcnden Dutzende von Weltraum-Startups und sammeln 3,6 Milliarden Dollar ein"}),"\n",(0,t.jsxs)(n.p,{children:["**Ehemalige SpaceX-Mitarbeiter gr\xfcnden Dutzende von Weltraum-Startups und bringen 3 Milliarden Dollar ein.\nEhemalige SpaceX-Mitarbeiter haben Dutzende von Weltraum-Startups gegr\xfcndet und 3,6 Milliarden Dollar aufgebracht, um Innovationen in den Bereichen Navigation im erdnahen Orbit und Nutzlasttransport voranzutreiben. Die Mitgr\xfcnder profitieren von der Gemeinschaft und der Risikotoleranz, die bei SpaceX entstanden sind, wobei die Startdienste auch den Versand von technischen Prototypen, Maschinen und Navigationssatelliten unterst\xfctzen. Die Software-as-a-Service-Industrie w\xe4chst und unterst\xfctzt das \xd6kosystem der Weltraum-Startups. Das Tempo von NASA und Boeing k\xf6nnte von der F\xf6rderung einer Startup-Kultur profitieren, da veralteter Code und Altlasten die etablierten Unternehmen bremsen. Chancen in der Weltraumforschung sorgen f\xfcr Liquidit\xe4t auf dem Markt, und Investoren erhalten Millionen f\xfcr riskante Mondlandungen. Einige Kommentare deuten darauf hin, dass der Artikel wie eine Pressemitteilung wirkt.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35404823",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://interactive.satellitetoday.com/via/april-2023/how-spacex-alums-are-branching-out-and-shaping-the-startup-economy/",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"spacexs-starship-bewegt-sich-zum-startplatz-start-m\xf6glicherweise-am-10-april",children:"SpaceX's Starship bewegt sich zum Startplatz, Start m\xf6glicherweise am 10. April"}),"\n",(0,t.jsxs)(n.p,{children:["**SpaceX verlegt Starship zum Startplatz, und der Start k\xf6nnte nur noch wenige Tage entfernt sein.\nSpaceX hat sein Starship auf einen Startplatz in S\xfcdtexas verlegt, der vorbehaltlich der FAA-Genehmigung bereits am 10. April zum Start bereit sein k\xf6nnte. Die riesige Super Heavy-Rakete soll der NASA als Mondlandeger\xe4t f\xfcr die Artemis-Mondmissionen dienen. SpaceX hat mehr als 1 Milliarde Dollar in seinen Start- und Auffangturm investiert, um das Starship und die Super Heavy zu unterst\xfctzen, die das Unternehmen in seiner Anlage in S\xfcdtexas eher vorsichtig entwickelt hat. Wenn dies gelingt, k\xf6nnte die niedrige Erdumlaufbahn f\xfcr Fachleute leichter zug\xe4nglich werden.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35405030",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://arstechnica.com/science/2023/04/spacex-moves-starship-to-launch-site-and-liftoff-could-be-just-days-away/",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"ccurlsh-erm\xf6glicht-es-curl-chrome-cookies-auf-eine-\xfcbersichtliche-weise-zu-nutzen",children:"ccurl.sh' erm\xf6glicht es cURL, Chrome-Cookies auf eine \xfcbersichtliche Weise zu nutzen."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Discussion Service anzeigen: Cookies von Chrome (CDP) in cURL ohne Copy-Paste verwenden"}),'.\n\'ccurl.sh\' ist ein Bash-Skript, das es cURL erlaubt, Chrome-Cookies zu verwenden, ohne ein GUI-Tool wie Postman zu ben\xf6tigen. Es verwendet das Chrome DevTools-Protokoll, um Cookies von einem bestimmten Tab der lokalen Chrome-Instanz in den Header eines cURL-Befehls zu kopieren und vermeidet das Auslaufen von Cookies in die Shell-History-Datei; das Skript ben\xf6tigt bash, websocat und jq, um zu laufen, und einen Tab mit den zu verwendenden Cookies, der in Chrome ge\xf6ffnet sein muss, der mit "google-chrome-stable --remote-debugging-port=9222" gestartet werden sollte, und kann installiert werden, indem man das Skript nach "/usr/bin/ccurl" kopiert und es ausf\xfchrbar macht.\n',(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35399218",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://github.com/fipso/ccurl.sh",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"mits-course-on-rnns--transformers-for-deep-learning",children:"MIT's Course on RNNs & Transformers for Deep Learning"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"MIT 6.S191: Rekurrente Neuronale Netze, Transformatoren und Aufmerksamkeit"}),".\nDer MIT-Kurs 6.S191 behandelt rekurrente neuronale Netze (RNNs), Transformatoren und Aufmerksamkeit f\xfcr Deep Learning, wie auf YouTube zu sehen ist. Die Kommentare zum Video reichen von der Infragestellung der Namenskonventionen f\xfcr die Parameter bis hin zu Empfehlungen, wo man neuronale Netze und Grundlagen des Deep Learning lernen kann. Die Verwendung von TensorFlow im Kurs und das Hochladen der Videos auf die YouTube-Kan\xe4le der einzelnen Mitarbeiter werden ebenfalls diskutiert.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35405338",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://www.youtube.com/watch?v=ySEx_Bqxvvo",children:"Artikel"}),"."]})]})}function o(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(u,{...e})}):u(e)}}}]);